from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test1")
async def test1(file: UploadFile = File(), form: str = Form()):
    return {"file": file.filename, "form": form}

@app.post("/test2")
async def test2(form: str = Form(), file: UploadFile = File()):
    return {"file": file.filename, "form": form}

client = TestClient(app)

def test_order_of_params():
    # File first, Form second
    response1 = client.post(
        "/test1",
        data={"form": "value"},
        files={"file": ("test.txt", b"content")}
    )
    assert response1.status_code == 200
    assert response1.json() == {"file": "test.txt", "form": "value"}

    # Form first, File second
    response2 = client.post(
        "/test2",
        data={"form": "value"},
        files={"file": ("test.txt", b"content")}
    )
    assert response2.status_code == 200
    assert response2.json() == {"file": "test.txt", "form": "value"}

if __name__ == "__main__":
    test_order_of_params()

